import {setupTelegram} from './telegram.js';
import {ICONS,planIcon} from './plan-icons.js';
import {microphoneHelp} from './microphone.js';
import {backupText,parseBackup,readDevice,writeDevice} from './backup.js';
import {setupUpdates} from './updates.js';
import {setupReminders,reminderFields,readReminderFields} from './reminders.js';
import {DEFAULT_REMINDERS,reminderSummary} from './reminders-core.js';
import {voiceButton,setupVoice} from './voice.js';
import {enhanceControls,refreshControls,closePicker} from './controls.js';
import {uid,key,date,add,monday,areas,initial,entries,occurrence,bounds,conflict,setOccurrence,coaching} from './core.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const svg=(path)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;
const icons={today:svg('<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 10h16m-11 5h6"/>'),week:svg('<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18M8 10v11m8-11v11"/>'),growth:svg('<path d="M12 21v-9m0 5C5 17 3 13 3 8c6 0 9 3 9 9Zm0-4c0-6 3-9 9-9 0 6-3 9-9 9Z"/>'),notes:svg('<path d="M14 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-9M8 8h3m-3 5h5m-5 5h8m0-12 2-2 3 3-2 2-5 2Z"/>'),settings:svg('<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor"/><circle cx="15" cy="17" r="3" fill="currentColor"/>'),plus:svg('<path d="M12 5v14M5 12h14"/>'),arrow:svg('<path d="m9 5 7 7-7 7"/>'),check:svg('<path d="m5 12 4 4L19 6"/>'),more:svg('<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'),note:svg('<path d="M8 4h12v12l-6 5H4V8m10 13v-6h6M3 4h8M7 1v7"/>'),download:svg('<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>')};
let updates,inlineEdited=false,pendingWrites=0,resume=null;
try{resume=JSON.parse(sessionStorage.getItem('gun-payi-resume')||'null')}catch{}
let db,state,view=['today','week','growth','notes','settings'].includes(new URLSearchParams(location.search).get('view'))?new URLSearchParams(location.search).get('view'):'week',today=key(),selected=today,weekStart=monday(today),noteQuery='',noteTag='',deferredInstall,registration,dirty=false,saveTimer,undoAction,lastSaved='',storageError=false,paused=false,updateRequested=false,quickKind='task',showCompleted=false,quickText='',plannerMode='week',monthAnchor=today.slice(0,7)+'-01',quickClock='';
if(view==='today')view='week';
const requestedDate=new URLSearchParams(location.search).get('date');if(requestedDate&&/^\d{4}-\d{2}-\d{2}$/.test(requestedDate)&&key(date(requestedDate))===requestedDate){selected=requestedDate;weekStart=monday(selected);monthAnchor=selected.slice(0,7)+'-01';}
try{const q=JSON.parse(localStorage.getItem('gun-payi-quick')||'null');if(q){quickText=String(q.text||'');quickKind=q.kind==='note'?'note':'task';quickClock=String(q.time||'');}}catch{}
const fmt=(d,opts)=>new Intl.DateTimeFormat('tr-TR',opts).format(date(d));
const pretty=d=>fmt(d,{day:'numeric',month:'long',weekday:'long'});
const short=d=>fmt(d,{day:'numeric',month:'short'});
const button=(text,action,cls='button',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const tagArea=i=>`<span class="area-dot ${esc(i.area)}"></span>${esc(areas[i.area]||'Kişisel')}`;
const toast=(msg,undo)=>{clearTimeout(saveTimer);$('#toast').innerHTML=`<span>${esc(msg)}</span>${undo?button('Geri al','undo','toast-undo'):''}`;$('#toast').className='show';undoAction=undo;saveTimer=setTimeout(()=>{$('#toast').className=''},undo?20000:6000)};
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('gun-payi',1);r.onupgradeneeded=()=>r.result.createObjectStore('local');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Depolama başka bir sekmede açık. Diğer sekmeyi kapatıp tekrar dene.'))})}
function readDB(){return new Promise((resolve,reject)=>{const tx=db.transaction('local','readonly'),r=tx.objectStore('local').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
let saveQueue=Promise.resolve();
function commit(fn,options={}){pendingWrites++;const task=saveQueue.then(()=>doCommit(fn,options));saveQueue=task.catch(()=>{});return task.finally(()=>pendingWrites--)}
async function doCommit(fn,options={}){if(paused)return;const baseRevision=state.revision||0,next=structuredClone(state);fn(next);next.revision=baseRevision+1;try{await new Promise((resolve,reject)=>{const tx=db.transaction('local','readwrite'),store=tx.objectStore('local'),r=store.get('state');r.onsuccess=()=>{if(r.result&&(r.result.revision||0)!==baseRevision){tx.abort();reject(Error('Başka bir sekmede değişiklik var. Bu formu kapatıp sayfayı yenile; girdilerin taslakta kalır.'));return}store.put(next,'state')};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(Error('Kayıt tamamlanamadı. Başka sekmedeki değişiklikleri kontrol et.'))});state=next;lastSaved=new Intl.DateTimeFormat('tr',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());storageError=false;if(options.render!==false)render();reminders.refresh();telegram.changed();return true}catch(e){storageError=true;toast(e.message||'Kaydedilemedi. Depolama alanını kontrol et.');return false}}
function nav(mobile=false){return [['week','Planım'],['notes','Notlar'],['growth','Gelişim']].map(([v,n],i)=>`${mobile&&i===2?button(icons.plus,'quick-capture','nav-add','aria-label="Hızlı ekle" title="Hızlı ekle"'):''}<button data-action="nav" data-view="${v}" class="nav-item ${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icons[v]}<span>${n}</span></button>`).join('')}
function animatePage(previous){if(previous===view||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const order=['week','notes','growth','settings'],direction=order.indexOf(view)>order.indexOf(previous)?1:-1;$('#main')?.animate?.([{opacity:0,transform:`translateY(7px) translateX(${direction*7}px)`},{opacity:1,transform:'translate(0,0)'}],{duration:210,easing:'cubic-bezier(.2,.7,.2,1)'});}
function saveReflectionQuietly(){const reflection=$('#reflection');if(reflection&&reflection.value!==(state.days[today]?.reflection||'')){const text=reflection.value;void commit(s=>{s.days[today]={...s.days[today],reflection:text}},{render:false});}}
function quickJump(){updates?.touch();saveReflectionQuietly();const previous=view;if(view!=='week'){if(!quickText)quickKind=view==='notes'?'note':'task';view='week';render();animatePage(previous);}const target=$('#quick-title');if(!target)return;const speech=state.prefs.quickVoice===true;$('.quick-capture').scrollIntoView({behavior:speech||matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});if(speech){voice.toggleFor('#quick-title');}else target.focus({preventScroll:true});}
function render(){voice.beforeRender();const liveReflection=$('#reflection')?.value,quickDraft=$('#quick-title')?.value??quickText,liveClock=$('[name=quickTime]')?.value;if(liveClock!==undefined)quickClock=liveClock;closePicker();today=key();const names={week:'Planım',notes:'Notlar',growth:'Gelişim',settings:'Ayarlar'};$('#app').innerHTML=`<a class="skip-link" href="#main">İçeriğe geç</a><aside class="sidebar"><a class="brand" href="/" aria-label="Gün Payı, planım"><span class="brand-mark">${svg('<path d="M6 13a6 6 0 0 1 12 0M3 17h18M12 3v2M4.6 6.6 6 8m12 0 1.4-1.4"/>')}</span><span>gün payı</span></a><nav aria-label="Ana gezinme">${nav()}</nav><div class="sidebar-bottom">${button(icons.settings+'<span>Ayarlar</span>','nav','nav-item '+(view==='settings'?'active':''),'data-view="settings"')}<span class="local-label">${navigator.onLine?'Bu cihazda saklanır':'Çevrimdışı'}</span></div></aside><div class="workspace"><header class="topbar"><span class="topbar-context"><span class="mobile-brand">gün payı</span><span class="desktop-context">${names[view]}</span></span><div class="topbar-actions"><span class="save-status ${storageError?'error':''}">${storageError?'Kaydedilemedi':lastSaved?'Kaydedildi':'Cihazında'}</span>${button(icons.today,'open-reminders','icon-button','aria-label="Hatırlatma ayarları" title="Hatırlatmalar"')}${button(icons.plus+'<span>Yeni '+(view==='notes'?'not':'plan')+'</span>',view==='notes'?'add-note':'add-task','button primary compact','aria-label="Yeni '+(view==='notes'?'not':'plan')+'"')}</div></header><main id="main" tabindex="-1" data-view="${view}">${view==='week'?weekView():`<div class="page-heading"><h1>${names[view]}</h1></div>${view==='growth'?growthView():view==='notes'?notesView():settingsView()}`}</main><footer class="app-footer"><span>gün payı</span><span>Her şey kendi yerinde.</span></footer></div><nav class="mobile-nav" aria-label="Mobil gezinme">${nav(true)}${button(icons.settings+'<span>Ayarlar</span>','nav','nav-item '+(view==='settings'?'active':''),'data-view="settings" aria-label="Ayarlar"')}</nav>`;if(liveReflection!==undefined&&$('#reflection'))$('#reflection').value=liveReflection;if(quickDraft&&$('#quick-title'))$('#quick-title').value=quickDraft;enhanceControls();}
function welcome(){return ''}
function row(i,compact=false,displayDay=selected){const done=i.status==='done',past=i.status==='postponed',time=i.date<displayDay&&bounds(i)?`00.00–${i.endTime?.replace(':','.')||''}`:i.time?`${i.time.replace(':','.')}${i.endTime?'–'+i.endTime.replace(':','.')+(i.endTime<=i.time?' +1':''):''}`:'Saati yok';return `<div class="plan-row ${done?'done':''} ${past?'postponed':''} ${i.rest?'rest-row':''}"><button class="completion ${done?'checked':''}" data-action="toggle" data-id="${i.id}" data-origin="${i.origin}" aria-label="${esc(i.title)}: ${done?'tamamlanmayı geri al':'tamamla'}" ${past?'disabled':''}>${done?icons.check:''}</button><button class="row-content" data-action="edit-item" data-id="${i.id}" data-origin="${i.origin}"><strong class="plan-title">${planIcon(i)}<span>${esc(i.title)}</span></strong><span class="row-meta">${!compact?`<span>${time}</span><span class="meta-sep">·</span>`:''}${tagArea(i)}${i.repeat!=='none'?'<span class="repeat-mark" title="Tekrarlayan">↻</span>':''}${i.rest?'<span>Dinlenme</span>':''}${past?'<span>Ertelendi</span>':''}${i.date<displayDay?'<span>Önceki günden</span>':''}</span></button>${!compact?button(icons.more,'item-menu','icon-button',`data-id="${i.id}" data-origin="${i.origin}" aria-label="${esc(i.title)} için işlemler"`):''}</div>`}
function quickCapture(){return `<div class="quick-capture" id="quick-capture"><div class="quick-capture-head"><div class="quick-tabs" role="group" aria-label="Hızlı ekleme türü">${button('Görev','quick-kind','quick-tab '+(quickKind==='task'?'active':''),'data-value="task" aria-pressed="'+(quickKind==='task')+'"')}${button('Not','quick-kind','quick-tab '+(quickKind==='note'?'active':''),'data-value="note" aria-pressed="'+(quickKind==='note')+'"')}</div>${button('Ayrıntılar',quickKind==='task'?'quick-details':'quick-note-details','button text-button')}</div><form id="quick-form"><label class="sr-only" for="quick-title">${quickKind==='task'?'Hızlı görev':'Hızlı not'}</label><div class="quick-entry">${quickKind==='note'?`<textarea id="quick-title" name="quickTitle" maxlength="20000" rows="2" required placeholder="Notunu yaz veya söyle…"></textarea>`:`<input id="quick-title" name="quickTitle" maxlength="500" required placeholder="Görev yaz veya söyle…" autocomplete="off">`}${voiceButton('#quick-title','Türkçe sesle yaz','voice-button quick-voice')}${button('Ekle','quick-submit','button primary','aria-label="'+(quickKind==='task'?'Görevi ekle':'Notu ekle')+'"')}</div>${quickKind==='task'?`<div class="quick-schedule"><label><span class="sr-only">Görev tarihi</span><input type="date" name="quickDate" required value="${selected}"></label><label><span class="sr-only">Görev saati</span><input type="time" name="quickTime" value="${quickClock}" placeholder="Saat ekle"></label><span class="quick-schedule-hint">Saat isteğe bağlı</span></div>`:''}</form></div>`}

function plannerTime(i,d){if(!i.time)return '';if(i.date<d)return `00:00–${i.endTime||''}`;return i.time+(i.endTime?'–'+i.endTime+(i.endTime<=i.time?' +1':''):'')}
function monthShift(d,n){const x=date(d);x.setDate(1);x.setMonth(x.getMonth()+n);return key(x)}
function plannerDay(d,small=false){const items=entries(state,d),pending=items.filter(i=>i.status==='pending');return `<button class="${small?'month-day':'week-day'} ${selected===d?'selected':''} ${today===d?'is-today':''} ${small&&d.slice(0,7)!==monthAnchor.slice(0,7)?'other-month':''}" data-action="select-day" data-date="${d}" aria-label="${pretty(d)}${pending.length?', '+pending.length+' plan':''}" aria-pressed="${selected===d}">${!small?`<span class="weekday-name">${fmt(d,{weekday:'short'})}</span>`:''}<strong>${date(d).getDate()}</strong><span class="day-indicators">${pending.slice(0,3).map(i=>`<i class="area-dot ${i.area}"></i>`).join('')}</span><span class="week-preview">${pending.slice(0,2).map(i=>`<span><small>${plannerTime(i,d)||'Esnek'}</small><span class="week-plan-label">${planIcon(i,true)}${esc(i.title)}</span></span>`).join('')}${pending.length>2?`<em>+${pending.length-2}</em>`:''}</span></button>`}
function weekView(){const days=Array.from({length:7},(_,i)=>add(weekStart,i));if(plannerMode!=='month'&&!days.includes(selected))selected=days.includes(today)?today:weekStart;const list=entries(state,selected),conflicts=new Set();for(let i=0;i<list.length;i++)for(let j=i+1;j<list.length;j++)if(conflict(list[i],list[j])){conflicts.add(list[i].occurrenceKey);conflicts.add(list[j].occurrenceKey)}const monthStart=monthAnchor,monthDays=Array.from({length:42},(_,i)=>add(monday(monthStart),i));return `<div class="planner-heading"><h1>Planım</h1><div class="view-switch" role="group" aria-label="Plan görünümü">${[['week','Hafta'],['list','Liste'],['month','Ay']].map(([v,t])=>button(t,'planner-mode','view-option '+(plannerMode===v?'selected':''),`data-value="${v}" aria-pressed="${plannerMode===v}"`)).join('')}</div></div><div class="planner-toolbar"><div class="week-pager">${button('‹','prev-week','icon-button',`aria-label="Önceki ${plannerMode==='month'?'ay':'hafta'}"`)}<h2>${plannerMode==='month'?fmt(monthAnchor,{month:'long',year:'numeric'}):`${short(weekStart)} – ${short(add(weekStart,6))}`}</h2>${button('›','next-week','icon-button',`aria-label="Sonraki ${plannerMode==='month'?'ay':'hafta'}"`)}</div><div class="inline-actions">${button('Bugün','this-week','button secondary small')}${button(icons.download,'calendar-export','icon-button','aria-label="Saatli planları takvime aktar" title="Takvime aktar"')}</div></div>${plannerMode==='week'?`<div class="week-strip" role="group" aria-label="Haftanın günleri">${days.map(d=>plannerDay(d)).join('')}</div>`:plannerMode==='month'?`<div class="month-weekdays">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map(d=>`<span>${d}</span>`).join('')}</div><div class="month-grid" role="group" aria-label="Ayın günleri">${monthDays.map(d=>plannerDay(d,true)).join('')}</div>`:''}<section class="section day-detail"><div class="day-detail-heading"><h2>${pretty(selected)}</h2><span>${selected===today?'Bugün':''}</span></div>${quickCapture()}${plannerMode==='list'?`<div class="week-agenda">${days.map(d=>{const items=entries(state,d);return `<section class="agenda-day"><button data-action="select-day" data-date="${d}" class="agenda-date ${d===today?'is-today':''}"><strong>${date(d).getDate()}</strong><span>${fmt(d,{weekday:'short'})}</span></button><div class="agenda-day-content">${items.length?items.map(i=>row(i,false,d)).join(''):'<p class="empty-day">Plan yok</p>'}</div></section>`}).join('')}</div>`:`${conflicts.size?'<p class="notice warning">Bazı saatler çakışıyor. İstersen planı düzenleyebilirsin.</p>':''}<div class="agenda-list">${list.some(i=>i.status!=='done')?list.filter(i=>i.status!=='done').map(i=>`<div class="${conflicts.has(i.occurrenceKey)?'has-conflict':''}">${row(i)}</div>`).join(''):'<div class="empty-state"><p>Bu günün açık planı yok.</p></div>'}</div>${list.some(i=>i.status==='done')?`<details class="completed-plans"><summary>Tamamlananlar · ${list.filter(i=>i.status==='done').length}</summary>${list.filter(i=>i.status==='done').map(i=>row(i)).join('')}</details>`:''}`}</section>`}
const goalTemplates={english:{title:'İngilizceye yeniden başlamak',why:'Konuşurken daha rahat olmak.',step:'Bu hafta iki kısa sohbet.',normal:'10 dakika İngilizce sohbet',hard:'İngilizce iki cümle kur'},curiosity:{title:'Merak ettiğim bir şeyi öğrenmek',why:'Kendi ilgilerime yer açmak.',step:'İlgimi çeken bir konu seç.',normal:'10 dakika oku ve bir not al',hard:'Tek bir soruyu not et'},movement:{title:'Hareket ve dinlenmeye yer açmak',why:'Günün içinde daha iyi hissetmek.',step:'Arkadaşımla iki yürüyüş günü seç.',normal:'Birlikte yaklaşık bir saat yürü',hard:'5 dakika dışarı çık veya dinlen'},faith:{title:'İbadete kendi tempomda dönmek',why:'Manevi yönüme zaman ayırmak.',step:'Sürdürebileceğim bir başlangıç seç.',normal:'Kendime uygun bir ibadet zamanı ayır',hard:'Kısa bir dua için dur'},social:{title:'Yakınlarımla bağımı korumak',why:'İlişkilerimi gündelik hayatımda tutmak.',step:'Babaannemi aramak için bir gün seç.',normal:'10 dakika konuş',hard:'Kısa bir hâl hatır mesajı gönder'},self:{title:'Küçük sözlerimi tutmak',why:'Kendi kararlarımın arkasında durmak.',step:'Bu hafta küçük ve net bir taahhüt seç.',normal:'Seçtiğim küçük işi tamamla',hard:'Adımı daha küçük hâle getir'}};
function growthView(){return `<p class="page-intro">Büyük hedeflerden önce, bu hafta atabileceğin küçük bir adım.</p><div class="growth-list">${Object.keys(goalTemplates).map(a=>{const g=state.goals.find(g=>g.area===a),t=g||goalTemplates[a];return `<section class="growth-row"><div class="growth-label"><span class="area-dot ${a}"></span><h2>${areas[a]}</h2>${!g?'<span class="suggestion-label">ÖRNEK HEDEF</span>':''}</div><div class="growth-content"><h3>${esc(t.title)}</h3><p>${esc(t.step)}</p><div class="goal-options"><span><small>Normal gün</small>${esc(t.normal)}</span><span><small>Zor gün</small>${esc(t.hard)}</span></div>${g?`<div class="goal-log"><span>${g.log.length?`Son adım: ${short(g.log.at(-1).date)} · ${g.log.at(-1).mode==='normal'?'Normal gün':'Zor gün'}`:'Henüz adım kaydı yok.'}</span>${button('Adım kaydet','goal-log','button text-button',`data-id="${g.id}"`)}${g.log.length?button('Son kaydı geri al','undo-goal-log','button text-button small',`data-id="${g.id}"`):''}</div>`:'<p class="fine">Örnek içerik. Onaylamadan hedeflerine eklenmez.</p>'}</div>${button(g?'Düzenle':'Kendime uyarla','edit-goal','button secondary small',`data-area="${a}"`)}</section>`}).join('')}</div><div class="faith-privacy"><p>Bu alan kişiseldir; puanlama veya başkalarıyla karşılaştırma içermez.</p></div>${coachView()}<details class="journal"><summary>Bugünkü gün notum</summary><label for="reflection">Bugünden geriye kalan</label><textarea id="reflection" rows="3" maxlength="10000">${esc(state.days[today]?.reflection||'')}</textarea>${button('Kaydet','save-reflection','button secondary small')}</details>`}
function coachView(){const c=coaching(state,today);return `<section class="section coach"><div class="section-title"><h2>Planından bir not</h2><span class="muted">Kayıtlarına göre</span></div>${c.length?c.map(x=>`<div class="coach-line"><strong>${esc(x.title)}</strong><p>${esc(x.text)}</p></div>`).join(''):'<p class="subtext">Biraz kullandıktan sonra, tekrar ertelenen veya aynı güne yığılan adımlar burada görünür.</p>'}<p class="fine">Öneriler kayıtlı planlarına uygulanan basit kurallardan oluşur.</p></section>`}
const noteKinds={remember:'Unutmamam gereken',heard:'Birinden duyduğum',idea:'Bir fikir',learning:'Öğrendiğim konu',conversation:'Sohbet için aklımda'};
function filteredNotes(){return state.notes.filter(n=>(!noteTag||n.kind===noteTag)&&`${n.text} ${n.tag} ${n.recall} ${n.use}`.toLocaleLowerCase('tr').includes(noteQuery.toLocaleLowerCase('tr'))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))}
function noteCards(){const list=filteredNotes();return list.length?list.map(n=>`<article class="note-card"><div class="note-card-top"><span class="tiny-label">${noteKinds[n.kind]||'NOT'}</span>${button(icons.more,'edit-note','icon-button',`data-id="${n.id}" aria-label="Notu aç ve düzenle"`)}</div><button class="note-body" data-action="edit-note" data-id="${n.id}">${esc(n.text)}</button><div class="note-card-bottom"><span>${n.tag?`#${esc(n.tag)} · `:''}${short(key(new Date(n.createdAt)))}</span>${n.convertedItemId?'<span>Plana dönüştürüldü</span>':button('Plana dönüştür '+icons.arrow,'convert-note','button text-button small',`data-id="${n.id}"`)}</div></article>`).join(''):`<div class="empty-state wide"><span class="empty-illustration">${icons.notes}</span><h2>${noteQuery||noteTag?'Aradığın not bulunamadı.':'Bir cümle bile yeterli.'}</h2><p>${noteQuery||noteTag?'Aramayı veya filtreyi değiştirebilirsin.':'Aklındaki bir fikri, birinden duyduğunu veya sonraki sohbette soracağın soruyu buraya bırak.'}</p>${!noteQuery&&!noteTag?button('İlk notunu yaz '+icons.plus,'add-note','button primary'):''}</div>`}
function notesView(){return `<div class="notes-toolbar"><label class="search-field"><span class="sr-only">Notlarda ara</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></svg><input id="note-search" type="search" placeholder="Notlarında ara…" value="${esc(noteQuery)}"></label>${button(icons.plus+' Not yaz','add-note','button primary')}</div><div class="note-filters" aria-label="Not türü">${button('Tümü','note-filter','filter '+(!noteTag?'selected':''),'data-value=""')}${Object.entries(noteKinds).map(([v,t])=>button(t,'note-filter','filter '+(v===noteTag?'selected':''),`data-value="${v}"`)).join('')}</div><div id="note-cards" class="note-grid">${noteCards()}</div>`}
function notificationSettings(){const permission=reminders.permission(),enabled=state.prefs.notifyEnabled!==false;let voiceDraft=false;try{voiceDraft=Boolean(JSON.parse(localStorage.getItem('gun-payi-voice'))?.text)}catch{}return `<section class="settings-section" id="reminder-settings"><div class="section-title"><h2>Bu cihazdaki bildirimler</h2><span class="setting-status">${permission==='granted'&&enabled?'Açık · uygulama açıkken':permission==='granted'?'Kapalı':permission==='denied'?'İzin kapalı':permission==='unsupported'?'Desteklenmiyor':'İzin gerekiyor'}</span></div><p id="local-reminder-status" class="fine">${esc(reminders.diagnostic())}</p><p>Sistem bildirimleri uygulama açıkken çalışır. Uygulama kapalıyken PWA bildirimi gönderilmez; arka planda zamanında teslim garantisi yoktur.</p><div class="inline-actions">${permission==='granted'&&enabled?button('Kapat','disable-notifications','button secondary small'):button('Bildirimleri aç','enable-notifications','button primary small')}${button('Tarayıcı bildirimi dene','test-notification','button text-button')}</div><form id="reminder-prefs-form"><label>Varsayılan süreler</label>${reminderFields({values:state.prefs.reminderDefaults??DEFAULT_REMINDERS,global:true})}<button type="submit" class="button secondary">Süreleri kaydet</button></form><div class="calendar-option"><h3>Kapalıyken telefon takvimin hatırlatsın</h3><p>Önümüzdeki 90 günün saatli planlarını ve hatırlatmalarını takvim dosyasına aktar. Dosyayı telefon takviminde içe aktar; takvim uygulamasının alarm desteği gerekir. Sonraki değişiklikler takvimdeki kopyaya otomatik yansımaz.</p>${button('Takvime aktar (.ics)','calendar-export','button secondary')}</div>${voiceDraft?button('Yarım kalan ses metnini not olarak aç','recover-voice','button text-button'):''}</section>`}
function settingsView(){const shift=state.items.find(i=>i.id==='work-shift');return `<div class="settings-layout"><section class="settings-section"><h2>Düzenim</h2><form id="prefs-form"><label>Adın<input name="name" maxlength="100" value="${esc(state.prefs.name)}" autocomplete="given-name"></label><label>Haftalık değerlendirme günü<select name="reviewDay">${['Pazar','Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi'].map((n,i)=>`<option value="${i}" ${state.prefs.reviewDay===i?'selected':''}>${n}</option>`).join('')}</select></label><button class="button secondary" type="submit">Kaydet</button></form><div class="setting-line"><div><h3>Vardiya</h3><p>${shift?`${shift.time}–${shift.endTime}${shift.endTime<=shift.time?' · ertesi gün':''}`:'Henüz eklenmedi'}</p></div>${button('Düzenle','edit-shift','button text-button')}</div></section>${telegram.render()}${notificationSettings()}<section class="settings-section"><h2>Yedekler</h2><p>Plan ve notların bu cihazdaki tarayıcıda saklanır. Otomatik eşitleme yoktur. Adın, tüm planların, notların, hedeflerin, ayarların ve taslakların tek JSON yedeğinde kopyalanır.</p><div class="backup-actions">${button('Yedeği kopyala','export','button primary')}${button('Yedeği yapıştır','import','button secondary')}</div><p class="fine">Yapıştırma, bu cihazdaki verileri yedekteki verilerle değiştirir. Ardından Geri al ile dönebilirsin. Pano izni istenebilir.</p></section><section class="settings-section"><h2>Uygulama</h2><div class="setting-line"><div><h3>Telefona kurulum</h3><p>İlk yüklemeden sonra plan ve notlarını çevrimdışı kullanabilirsin.</p></div>${button('Kurulum','install','button text-button')}</div><div class="setting-line quick-add-setting"><label class="check-label"><input type="checkbox" id="quick-voice" ${state.prefs.quickVoice?'checked':''}><span><strong>+ ile sesle başla</strong><small>Kapalıyken ekleme alanını açar; açıkken aynı alanda Türkçe dikteyi de başlatır.</small></span></label></div><p class="fine">Güncellemeler uygulama açıkken ve yeniden öne geldiğinde kontrol edilir. Yazarken veya konuşurken bekler; verilerin korunur, yeniden kurulum gerekmez.</p>${button('Güncellemeleri kontrol et','check-update','button text-button')}<details id="microphone-settings"><summary>Mikrofon izni</summary><p id="microphone-permission">${voice.permissionLabel()}</p>${button('Mikrofon iznini kontrol et','microphone-authorize','button secondary small')}<p class="fine">${microphoneHelp({userAgent:navigator.userAgent})}</p></details><details><summary>Sesle yazma</summary><p>Mikrofona dokun, Türkçe konuş; metin doğrudan alana yazılır. Tekrar dokunarak veya Ekle’ye basarak durdurabilirsin. Ses tanıma tarayıcının hizmetinde işlenebilir ve internet gerektirebilir. Ses kaydı saklanmaz.</p></details></section><section class="settings-section"><h2>Geçmiş</h2>${button('Kayıt geçmişi','history','button secondary')}${button('Haftayı değerlendir','review','button text-button')}<p class="fine">Gün Payı · 4.1.1</p></section><section class="settings-section danger-zone"><h2>Verileri sıfırla</h2><p>Bu cihazdaki plan, not ve tercihleri siler.</p>${button('Bütün verileri sil','reset','button danger')}</section></div>`}
function modal(content,kind='',meta={}){const d=$('#modal');d.innerHTML=`<div class="modal-shell">${content}</div>`;d.dataset.kind=kind;d._meta=meta;dirty=false;if(!d.open)d.showModal();d.scrollTop=0;enhanceControls(d);d.setAttribute('aria-label',d.querySelector('h2')?.textContent||'Gün Payı');const f=d.querySelector('input:not([type=checkbox]):not([type=hidden]),textarea');if(f&&matchMedia('(min-width:700px)').matches)setTimeout(()=>f.focus(),50)}
function head(title,sub=''){return `<div class="modal-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${button('×','close-modal','icon-button close-button','aria-label="Pencereyi kapat"')}</div>`}
function foot(text='Kaydet'){return `<div id="form-error" role="alert" class="form-error"></div><footer class="modal-footer">${button('Vazgeç','close-modal','button secondary')}<button class="button primary" type="submit">${text}</button></footer>`}
function itemEditor(id,origin,preset={}){const base=state.items.find(i=>i.id===id),i=base?occurrence(base,origin||base.date):{title:'',kind:'task',date:selected,time:'',endTime:'',area:'personal',repeat:'none',weekdays:[],optional:true,priority:false,buffer:0,detail:'',...preset},defaults=state.prefs.reminderDefaults??DEFAULT_REMINDERS;modal(`${head(base?'Planı düzenle':'Yeni plan')}<form id="item-form">${base&&base.repeat!=='none'?`<label>Değişiklik<select name="scope" id="edit-scope"><option value="one">Sadece bu gün</option><option value="series">Serinin tamamı</option></select></label>`:''}<label class="title-label">Başlık<div class="input-with-voice"><input required name="title" aria-label="Başlık" maxlength="500" value="${esc(i.title)}" placeholder="Ne yapmak istiyorsun?" autocomplete="off">${voiceButton('#item-form [name=title]','Türkçe sesle yaz')}</div></label><div class="form-grid"><label>Tarih<input type="date" name="date" required value="${i.date}"></label><label>Saat<input type="time" name="time" value="${i.time||''}"></label></div><details ${i.endTime||i.repeat!=='none'?'open':''}><summary>Tekrar ve diğer ayrıntılar</summary><div class="form-grid"><label>Bitiş<input type="time" name="endTime" value="${i.endTime||''}"></label><label>Tür<select name="kind" id="item-kind">${[['task','Görev'],['event','Etkinlik'],['habit','Alışkanlık']].map(([v,t])=>`<option value="${v}" ${i.kind===v?'selected':''}>${t}</option>`).join('')}</select></label></div><label>Simge<select name="icon">${Object.entries(ICONS).map(([v,t])=>`<option value="${v}" ${(i.icon||'auto')===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Alan<select name="area">${Object.entries(areas).map(([v,t])=>`<option value="${v}" ${i.area===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Tekrar<select name="repeat" id="repeat-select">${[['none','Bir kez'],['daily','Her gün'],['weekly','Seçtiğim günlerde']].map(([v,t])=>`<option value="${v}" ${i.repeat===v?'selected':''}>${t}</option>`).join('')}</select></label><fieldset id="weekday-fields" ${i.repeat==='weekly'?'':'hidden'}><legend>Günler</legend><div class="weekday-checks">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="weekdays" value="${d}" ${i.weekdays.includes(d)?'checked':''}><span>${['Paz','Pzt','Sal','Çar','Per','Cum','Cmt'][d]}</span></label>`).join('')}</div></fieldset><div class="form-grid"><label>Hazırlık / ulaşım (dk.)<input name="buffer" type="number" min="0" max="240" value="${i.buffer||0}"></label><label>Tekrarın son günü<input name="until" type="date" value="${i.until||''}"></label></div><label class="check-label"><input type="checkbox" name="priority" ${i.priority?'checked':''}> Öncelikli</label><label class="check-label"><input type="checkbox" name="optional" ${i.optional?'checked':''}> Gerekirse hafifletilebilir</label><label class="check-label"><input type="checkbox" name="rest" ${i.rest?'checked':''}> Dinlenme aralığı</label><p class="fine">Bitiş başlangıçtan erkense ertesi gün kabul edilir.</p></details><details><summary>Hatırlatmalar · ${esc(reminderSummary(i.reminders??defaults))}</summary><p class="fine">Saat eklenmiş planlar için geçerli. Tarayıcı bildirimi uygulama açıkken çalışır. Telegram servisi bağlıysa bu süreler sunucuya da aktarılır.</p>${reminderFields({values:i.reminders??defaults,inherit:i.reminders===undefined||i.reminders===null,defaults})}</details><details ${i.detail?'open':''}><summary>Not</summary><label class="sr-only" for="item-detail">Kısa not</label><textarea id="item-detail" name="detail" rows="3" maxlength="20000">${esc(i.detail||'')}</textarea></details><div id="conflict-preview" class="fine"></div>${foot(base?'Kaydet':'Ekle')}</form>`,'item',{id,origin:origin||i.date,noteId:preset.noteId,baseRepeat:base?.repeat,quickSource:preset.quickSource||false});scopeFields();}
function scopeFields(){const f=$('#item-form');if(!f)return;const one=f.scope?.value==='one';for(const name of ['kind','repeat','until'])f.elements[name].disabled=one;f.querySelectorAll('[name=weekdays]').forEach(x=>x.disabled=one);refreshControls()}
function noteEditor(id,presetText='',quickSource=false){const n=state.notes.find(x=>x.id===id)||{text:presetText,kind:'remember',tag:'',recall:'',use:'',reviewDates:[],reviewedDates:[]};modal(`${head(id?'Notunu aç':'Hızlı not','Aklındakini kaydet; sonra düzenleyebilirsin.')}<form id="note-form"><label>Notun<textarea name="text" required rows="5" maxlength="20000" placeholder="Unutmamak istediğin şey…">${esc(n.text)}</textarea></label><div class="field-voice-row">${voiceButton('#note-form [name=text]','Notu Türkçe sesle yaz')}</div><div class="form-grid"><label>Not türü<select name="kind" id="note-kind">${Object.entries(noteKinds).map(([v,t])=>`<option value="${v}" ${n.kind===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Etiket <span class="muted">isteğe bağlı</span><input name="tag" maxlength="200" placeholder="iş, kitap, sohbet…" value="${esc(n.tag)}"></label></div><details id="learning-details" ${n.kind==='learning'?'open':''}><summary>Hatırlamaya yardımcı sorular</summary><p class="fine">Yukarıdaki not: “Ne öğrendim?”</p><label>Bakmadan nasıl anlatırım?<textarea name="recall" rows="2" maxlength="20000">${esc(n.recall)}</textarea></label><label>Nerede kullanabilirim?<textarea name="use" rows="2" maxlength="20000">${esc(n.use)}</textarea></label><label class="check-label"><input name="review" type="checkbox" ${n.reviewDates.length?'checked':''}> Bugünden 1, 3 ve 7 gün sonra tekrar öner</label><p class="fine">Tekrarlar uygulamayı açtığında görünür; kapalıyken bildirim göndermez.</p></details>${id&&n.reviewDates.some(d=>d<=today&&!n.reviewedDates.includes(d))?button('Bugünkü tekrarı yaptım','review-note','button secondary',`data-id="${id}"`):''}${id?`<div class="note-edit-actions">${button('Plana dönüştür','convert-note','button text-button',`data-id="${id}"`)}${button('Notu sil','delete-note','button danger text-button',`data-id="${id}"`)}</div>`:''}${foot()}</form>`,'note',{id,quickSource});}
function goalEditor(area){const g=state.goals.find(g=>g.area===area),v=g||goalTemplates[area];modal(`${head(areas[area],g?'Hedefini kendi hayatına göre düzenle.':'Düzenlenebilir örnek. Kaydetmeden eklenmez.')}<form id="goal-form"><label>Hedef<input required name="title" maxlength="2000" value="${esc(v.title)}"></label><label>Neden benim için önemli?<textarea name="why" rows="2" maxlength="2000">${esc(v.why)}</textarea></label><label>Bu hafta atacağım küçük adım<textarea name="step" rows="2" maxlength="2000">${esc(v.step)}</textarea></label><label>Normal gün seçeneği<input name="normal" maxlength="2000" value="${esc(v.normal)}"></label><label>Zor gün seçeneği<input name="hard" maxlength="2000" value="${esc(v.hard)}"></label><p class="fine">Tekrar eden bir adımı ajandana eklemek için kaydettikten sonra “Planına ekle”yi kullanabilirsin.</p>${g?`<div class="inline-actions">${button('Planına ekle','plan-goal','button text-button',`data-id="${g.id}"`)}${button('Hedefi sil','delete-goal','button danger text-button',`data-id="${g.id}"`)}</div>`:''}${foot(g?'Hedefi kaydet':'Hedefi benimse')}</form>`,'goal',{area,id:g?.id});}
const reviewQuestions=['Bu hafta ne iyi geldi?','Nerede plan fazla ağırdı?','Hangi iş neden aksadı?','Önümüzdeki hafta neyi azaltacağım?','Neyi sürdürmek istiyorum?'];
function reviewEditor(){const week=view==='week'?weekStart:monday(today),r=state.reviews.find(x=>x.week===week);modal(`${head('Haftadan ne kalsın?',`${short(week)} — ${short(add(week,6))} · Beş dakika, kısa cevaplar.`)}<form id="review-form">${reviewQuestions.map((q,i)=>`<label>${q}<textarea name="answer${i}" rows="2" maxlength="20000" placeholder="İstersen boş bırakabilirsin.">${esc(r?.answers[i]||'')}</textarea></label>`).join('')}${foot('Değerlendirmeyi kaydet')}</form>`,'review',{week});}
function onboarding(){const shift=state.items.find(i=>i.id==='work-shift');modal(`${head('Haftanın temelini doğrula','Diğer saatleri bilmeden doldurmayacağız.')}<form id="onboarding-form"><div class="notice">Pazartesi–cumartesi çalışma, pazar izin başlangıç düzenidir. Günleri daha sonra değiştirebilirsin.</div><div class="form-grid"><label>Vardiya başlangıcı<input type="time" name="time" required value="${shift?.time||'16:00'}"></label><label>Bitiş <span class="muted">ertesi gün</span><input type="time" name="endTime" required value="${shift?.endTime||'01:00'}"></label></div><fieldset><legend>Şimdilik öncelik verdiğin alanlar</legend>${Object.keys(goalTemplates).map(a=>`<label class="check-label"><input type="checkbox" name="focus" value="${a}" ${state.prefs.focus.includes(a)?'checked':''}> ${areas[a]}</label>`).join('')}</fieldset><p class="fine">Yürüyüş günlerini ve ilk etkinliklerini istediğin zaman ekleyebilirsin. Hiçbir öneri kendiliğinden planına eklenmez.</p>${foot('Düzenimi kaydet')}</form>`,'onboarding');}
async function closeModal(force=false){closePicker();clearTimeout(dialogDraftTimer);if(dirty&&!force){const f=$('#modal form');if(f){saveDraft();toast('Taslak saklandı. Yeniden açılışta devam edebilirsin.');}}$('#modal').close();dirty=false;}
function saveDraft(){const f=$('#modal form');if(!f)return;const fields=[...new FormData(f).entries()];try{localStorage.setItem('gun-payi-draft',JSON.stringify({kind:$('#modal').dataset.kind,meta:$('#modal')._meta,fields,at:Date.now()}));return true}catch{toast('Form taslağı saklanamadı. Kaydetmeden sayfayı kapatma.');return false}}
function clearDraft(){clearTimeout(dialogDraftTimer);try{localStorage.removeItem('gun-payi-draft')}catch{}}
function draftPrompt(){let d;try{d=JSON.parse(localStorage.getItem('gun-payi-draft'))}catch{}if(d?.fields&&['item','note','goal','review','onboarding','reflection'].includes(d.kind)){modal(`${head('Yarım kalan bir taslağın var')}<p>Girdiğin bilgileri yeniden açabilir veya taslağı silebilirsin.</p><div class="modal-footer">${button('Taslağı sil','discard-draft','button secondary')}${button('Devam et','restore-draft','button primary')}</div>`,'draft',{draft:d});return true}return false}
let confirmCallback,dialogDraftTimer;
function confirmDialog(title,text,fn,label='Onayla'){confirmCallback=fn;modal(`${head(title)}<p>${esc(text)}</p><div class="modal-footer">${button('Vazgeç','close-modal','button secondary')}${button(label,'confirm','button danger')}</div>`,'confirm');}
function findItem(id,origin){const i=state.items.find(x=>x.id===id);return i?occurrence(i,origin||i.date):null}
function itemMenu(id,origin){const i=findItem(id,origin);if(!i)return;modal(`${head(esc(i.title),pretty(i.date))}<div class="menu-list">${button('Planı düzenle veya başka güne taşı','edit-item','menu-button',`data-id="${id}" data-origin="${origin}"`)}${button(i.status==='done'?'Tamamlanmayı geri al':'Tamamlandı olarak işaretle','toggle','menu-button',`data-id="${id}" data-origin="${origin}"`)}${button(i.priority?'Ana önceliklerden çıkar':'Bu günün ana önceliklerine ekle','priority-toggle','menu-button',`data-id="${id}" data-origin="${origin}"`)}${button('Ertele ve yeniden planla','postpone','menu-button',`data-id="${id}" data-origin="${origin}"`)}${button(i.repeat==='none'?'Bu planı iptal et':'Yalnızca bu gerçekleşmeyi atla','cancel-item','menu-button danger-text',`data-id="${id}" data-origin="${origin}"`)}${button(i.repeat==='none'?'Planı tamamen sil':'Tekrarlayan seriyi tamamen sil','delete-item','menu-button danger-text',`data-id="${id}"`)}</div>`,'menu');}
function readQuick(){quickText='';quickClock='';quickKind='task';try{const q=JSON.parse(localStorage.getItem('gun-payi-quick')||'null');if(q){quickText=String(q.text||'');quickClock=String(q.time||'');quickKind=q.kind==='note'?'note':'task';}}catch{}}
function manualCopy(text){modal(`${head('Yedeğini kopyala')}<p>Tarayıcı panoya yazamadı. Metnin tamamını seçip kopyalayabilirsin.</p><label>JSON yedeğin<textarea id="backup-text" rows="9" readonly>${esc(text)}</textarea></label>${button('Tümünü seç','select-backup','button primary')}`,'backup-copy');$('#backup-text').focus();$('#backup-text').select();}
async function exportBackup(){if(pendingWrites)await saveQueue;let text;try{text=backupText(state,localStorage);}catch{toast('Yedek hazırlanamadı. Depolama alanını kontrol et.');return;}try{await navigator.clipboard.writeText(text);toast('Tüm verilerin JSON olarak kopyalandı. Güvenli bir yere yapıştır.');}catch{manualCopy(text);}}
let restoringBackup=false;
async function restoreBackup(text){if(restoringBackup)return;let data;try{data=parseBackup(text);}catch(err){toast(err.message+' Mevcut verilerin değişmedi.');return;}restoringBackup=true;let previous,previousStorage;try{await saveQueue;previous=structuredClone(state);previousStorage=writeDevice(localStorage,data.storage);const ok=await commit(s=>{const revision=s.revision;for(const k of Object.keys(s))delete s[k];Object.assign(s,data.state,{revision});},{render:false});if(!ok){writeDevice(localStorage,previousStorage);return;}voice.close();inlineEdited=false;plannerMode=state.prefs.plannerMode||'week';readQuick();if($('#quick-title'))$('#quick-title').value=quickText;closeModal(true);render();toast('Yedeğin geri yüklendi. Tüm verilerin hazır.',async()=>{const currentStorage=readDevice(localStorage);try{writeDevice(localStorage,previousStorage);if(!await commit(s=>{const revision=s.revision;for(const k of Object.keys(s))delete s[k];Object.assign(s,previous,{revision});},{render:false})){writeDevice(localStorage,currentStorage);return;}plannerMode=state.prefs.plannerMode||'week';readQuick();if($('#quick-title'))$('#quick-title').value=quickText;render();toast('Önceki verilerin geri getirildi.');}catch{toast('Geri alma tamamlanamadı.');}});}catch{toast('Yedek saklanamadı. Mevcut verilerin değişmedi.');}finally{restoringBackup=false;}}
function manualPaste(){modal(`${head('Yedeğini yapıştır')}<p>Panodan yedek okunamadı. JSON yedeğini aşağıya yapıştır; geçerliyse hemen geri yüklenir.</p><label>JSON yedeğin<textarea id="paste-backup" rows="8" placeholder="Buraya yapıştır…" spellcheck="false"></textarea></label>${button('Yedeği yükle','restore-pasted-backup','button primary')}`,'backup-paste');$('#paste-backup').focus();}
async function importDialog(){try{const text=await navigator.clipboard.readText();if(!text.trim()){manualPaste();return;}await restoreBackup(text);}catch{manualPaste();}}
function installDialog(){const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1,android=/Android/.test(navigator.userAgent),standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;modal(`${head(standalone?'Uygulama olarak açık':'Gün Payı telefonunda')}<div class="install-mark"><span class="brand-mark"><i></i><i></i><i></i><i></i></span></div><p>${standalone?'Gün Payı zaten bağımsız uygulama olarak çalışıyor.':ios?'Safari’de Paylaş düğmesine dokun. “Ana Ekrana Ekle”yi seç, ardından Ekle’ye dokun. Menüde görünmüyorsa Diğer seçeneklerini aç.':android?'Chrome menüsünü aç (⋮). “Uygulamayı yükle” veya “Ana ekrana ekle”yi seç.':'Tarayıcının adres çubuğundaki yükleme simgesini ya da menüdeki “Gün Payı uygulamasını yükle” seçeneğini kullan. iPhone’da Safari → Paylaş → Ana Ekrana Ekle.'}</p>${deferredInstall&&!standalone?button('Uygulamayı yükle','install-native','button primary'):''}<div class="notice">İlk başarılı açılışın ardından ajandan ve notların çevrimdışı çalışır. Kurulum yedekleme veya cihazlar arası eşitleme sağlamaz.</div><p class="fine">Uygulama kapalıyken zamanlanmış bildirim gönderilmez.</p>`,'install');}

const voice=setupVoice({notify:toast,onRecover:text=>noteEditor(undefined,text)});
const reminders=setupReminders({getState:()=>state,commit,notify:toast});
const telegram=setupTelegram({getState:()=>state,notify:toast,canApply:()=>!telegram.isBusy()&&!voice.isOpen()&&!$('#modal').open&&!document.activeElement?.matches('input,textarea,[contenteditable=true]'),onConnected:({userId,url})=>commit(s=>{s.prefs.telegramUserId=userId;s.prefs.telegramService=url}),applyEvents:events=>commit(s=>{for(const event of events){if(event.type==='add'&&!s.items.some(i=>i.id===event.item.id))s.items.push({...event.item,history:event.item.history||[],detail:event.item.detail||''});if(event.type==='note'&&!s.notes.some(n=>n.id===event.note.id))s.notes.push(event.note);if(event.type==='patch'){const item=s.items.find(i=>i.id===event.itemId);if(item&&occurrence(item,event.origin).status!==event.patch.status)setOccurrence(s,event.itemId,event.origin,event.patch);}}})});

