'choose-priority':()=>{const list=entries(state,today).filter(x=>!x.priority&&x.status==='pending'&&(x.area!=='faith'||state.prefs.prayerVisible));modal(`${head('Bugün önemli olanı seç','En fazla üç ana öncelik.')}<div class="menu-list">${list.map(i=>button(esc(i.title),'priority-toggle','menu-button',`data-id="${i.id}" data-origin="${i.origin}"`)).join('')||'<p class="subtext">Henüz seçebileceğin başka plan yok.</p>'}</div>${button('Yeni bir öncelik ekle '+icons.plus,'add-priority','button primary')}`)},
