'walk-days':()=>modal(`${head('Birlikte yürüyüş','Öneri: haftada iki veya üç gün. Günleri sen seç.')}<form id="walk-form"><fieldset><legend>Hangi günler?</legend><div class="weekday-checks">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="weekdays" value="${d}"><span>${['Paz','Pzt','Sal','Çar','Per','Cum','Cmt'][d]}</span></label>`).join('')}</div></fieldset><div class="form-grid"><label>Başlangıç<input type="time" name="time" required value="09:00"></label><label>Bitiş<input type="time" name="endTime" required value="10:00"></label></div><p class="fine">Haftalık tekrar olarak eklenir. Tek bir günü sonradan taşıyabilir veya atlayabilirsin. Kahvaltı için istersen ayrı bir etkinlik ekle.</p>${foot('Yürüyüşleri ekle')}</form>`,'walk'),
