'delete-note':b=>{const id=b.dataset.id;confirmDialog('Not silinsin mi?','Bu not ve hatırlama tarihleri silinir.',async()=>{if(await commit(s=>{s.notes=s.notes.filter(x=>x.id!==id)})){clearDraft();closeModal(true);toast('Not silindi.')}},'Notu sil')},
