'restore-draft':()=>{const d=$('#modal')._meta.draft;if(d.kind==='item')itemEditor(d.meta.id,d.meta.origin,{noteId:d.meta.noteId,quickSource:d.meta.quickSource});else if(d.kind==='note')noteEditor(d.meta.id,'',d.meta.quickSource);else if(d.kind==='goal')goalEditor(d.meta.area);else if(d.kind==='review'){reviewEditor();$('#modal')._meta.week=d.meta.week}else if(d.kind==='onboarding')onboarding();else if(d.kind==='reflection'){view='growth';render();$('.journal').open=true;$('#reflection').value=d.fields.find(x=>x[0]==='reflection')?.[1]||'';closeModal(true);toast('Gün sonu taslağın geri getirildi. Kaydetmeyi unutma.');return}const f=$('#modal form');if(!f)return;const reminderDraft=f.querySelector('.reminder-fields');if(reminderDraft){const inherit=d.fields.some(([k])=>k==='inheritReminders'),values=inherit?(state.prefs.reminderDefaults??DEFAULT_REMINDERS):d.fields.filter(([k])=>k==='reminderOffset').map(([,v])=>Number(v));reminderDraft.outerHTML=reminderFields({values,inherit,defaults:state.prefs.reminderDefaults??DEFAULT_REMINDERS});}for(const x of f.querySelectorAll('input[type=checkbox]'))x.checked=false;for(const [k,v]of d.fields){const fields=[...f.elements].filter(x=>x.name===k);for(const el of fields)if(el.type==='checkbox'){if(el.value===v)el.checked=true}else el.value=v}refreshControls();scopeFields();if($('#weekday-fields'))$('#weekday-fields').hidden=f.repeat.value!=='weekly';dirty=true;saveDraft();toast('Taslağın geri getirildi.')},
history:()=>{const records=[];for(const i of state.items){for(const h of i.history)records.push({...h,title:i.title,id:i.id})}records.sort((a,b)=>b.at.localeCompare(a.at));modal(`${head('Kayıt geçmişi','En son değişiklikler. İptal edilen kayıtlar da burada korunur.')}<div class="history-list">${records.slice(0,150).map(h=>`<div><strong>${esc(h.title)}</strong><p>${pretty(h.origin)} · ${{pending:'Geri alındı / açık',done:'Tamamlandı',postponed:'Ertelendi',cancelled:'İptal edildi',edited:'Düzenlendi'}[h.action]||'Düzenlendi'} ${h.scope==='series'?'· Tüm seri':''}</p><small>${new Date(h.at).toLocaleString('tr-TR')}</small>${h.action==='cancelled'?button('Bu gerçekleşmeyi aç','restore-item','button text-button small',`data-id="${h.id}" data-origin="${h.origin}"`):''}</div>`).join('')||'<p>Henüz kaydedilmiş bir değişiklik yok.</p>'}</div>`,'history')},
