document.addEventListener('input',e=>{updates?.touch();if(e.target.closest('#prefs-form,#reminder-prefs-form'))inlineEdited=true;if(e.target.name==='quickTime'){quickClock=e.target.value;try{localStorage.setItem('gun-payi-quick',JSON.stringify({kind:quickKind,text:quickText,time:quickClock}))}catch{}return}if(e.target.id==='quick-title'){quickText=e.target.value;try{localStorage.setItem('gun-payi-quick',JSON.stringify({kind:quickKind,text:quickText,time:quickClock}))}catch{toast('Hızlı taslak saklanamadı. Ekle düğmesiyle kaydet.')}return}if(e.target.id==='note-search'){noteQuery=e.target.value;$('#note-cards').innerHTML=noteCards();return}if(e.target.id==='reflection'){try{localStorage.setItem('gun-payi-draft',JSON.stringify({kind:'reflection',fields:[['reflection',e.target.value]],meta:{},at:Date.now()}))}catch{toast('Taslak saklanamadı. Notunu Kaydet düğmesiyle kaydet.')}return}if(e.target.closest('#modal form')){dirty=true;clearTimeout(dialogDraftTimer);dialogDraftTimer=setTimeout(saveDraft,300)}if(e.target.closest('#item-form'))conflictPreview();});
function conflictPreview(){const f=$('#item-form');if(!f)return;const a={date:f.elements.date.value,time:f.time.value,endTime:f.endTime.value,buffer:Number(f.buffer.value),occurrenceKey:'preview'};const list=entries(state,a.date).filter(x=>x.id!==$('#modal')._meta.id);$('#conflict-preview').textContent=list.some(x=>conflict(a,x))?'Bu saatler veya tampon süre başka bir planla çakışıyor. Kaydetmene engel değil.':'';}
document.addEventListener('change',async e=>{if(e.target.id==='quick-voice'){const input=e.target,checked=input.checked;if(!await commit(s=>s.prefs.quickVoice=checked,{render:false}))input.checked=!checked;return;}if(e.target.id==='repeat-select')$('#weekday-fields').hidden=e.target.value!=='weekly';if(e.target.id==='edit-scope'){scopeFields();const base=state.items.find(i=>i.id===$('#modal')._meta.id);if(e.target.value==='series')$('#item-form').elements.date.value=base.date;else $('#item-form').elements.date.value=occurrence(base,$('#modal')._meta.origin).date;}if(e.target.id==='note-kind'&&e.target.value==='learning')$('#learning-details').open=true;if(e.target.id==='prayer-visible')await commit(s=>s.prefs.prayerVisible=e.target.checked);});
