async function refreshState(){if(!state||pendingWrites)return;const seenRevision=state.revision,latest=await readDB().catch(()=>null);if(pendingWrites||state.revision!==seenRevision)return;if(latest&&latest.revision!==state.revision){if($('#modal').open||voice.isOpen()||inlineEdited||$('#reflection')&&$('#reflection').value!==(state.days[today]?.reflection||'')){toast('Başka sekmede değişiklik var. Formunu kaydetmeden yenileme.');}else{state=latest;plannerMode=state.prefs.plannerMode||'week';render();}}else if(today!==key())render();}
