function restoreResume(){if(!resume||typeof resume!=='object')return;if(['week','notes','growth','settings'].includes(resume.view))view=resume.view;for(const [k,v] of Object.entries(resume.dates||{}))if(typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&key(date(v))===v){if(k==='selected')selected=v;if(k==='weekStart')weekStart=v;if(k==='monthAnchor')monthAnchor=v;}}
async function rememberUI(){try{const f=$('#modal form');if(voice.isOpen()){await voice.finishFor(document.body);}if(f&&['item','note','goal','review','onboarding'].includes($('#modal').dataset.kind)&&!saveDraft())return false;const quick=$('#quick-title');if(quick)localStorage.setItem('gun-payi-quick',JSON.stringify({text:quick.value,kind:quickKind,time:$('[name=quickTime]')?.value||quickClock}));const reflection=$('#reflection');if(reflection&&reflection.value!==(state.days[today]?.reflection||''))localStorage.setItem('gun-payi-draft',JSON.stringify({kind:'reflection',fields:[['reflection',reflection.value]],meta:{},at:Date.now()}));await saveQueue;sessionStorage.setItem('gun-payi-resume',JSON.stringify({view,dates:{selected,weekStart,monthAnchor},scroll:scrollY,hadModal:Boolean(f&&$('#modal').open),inlineEdited,forms:[...document.querySelectorAll('#prefs-form,#reminder-prefs-form')].map(f=>({id:f.id,fields:[...new FormData(f).entries()]}))}));return !storageError;}catch{return false;}}
function finishResume(){if(!resume)return;inlineEdited=Boolean(resume.inlineEdited);for(const saved of resume.forms||[]){const f=document.getElementById(saved.id);if(!f)continue;for(const input of f.querySelectorAll('input[type=checkbox]'))input.checked=false;for(const [name,value] of saved.fields||[])for(const el of [...f.elements].filter(x=>x.name===name)){if(el.type==='checkbox'){if(el.value===value)el.checked=true;}else el.value=value;}if(saved.id==='prefs-form')inlineEdited=f.elements.name.value!==state.prefs.name||Number(f.elements.reviewDay.value)!==state.prefs.reviewDay;}refreshControls();if($('#modal').dataset.kind==='draft'){if(resume.hadModal)actions['restore-draft']();else closeModal(true);}if(Number.isFinite(resume.scroll))requestAnimationFrame(()=>scrollTo({top:resume.scroll,behavior:'instant'}));try{sessionStorage.removeItem('gun-payi-resume')}catch{}resume=null;}
